const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const state={server:'',player:null,data:null,names:{},tab:'overview',listViews:{}};
const reportState={offset:0,limit:50,total:0,query:''};
const catalogNameCache={};
const catalogRowCache={};
const resourceOptionCache={};
const nameLoadPending={};
let assetTypeOptionCache=null;
async function api(path,opts={}){const headers=opts.body instanceof FormData?{}:{'Content-Type':'application/json'};const res=await fetch('/api/'+path,{headers,...opts});if(res.status===401){location.assign('/login');throw new Error('登录已失效')}let data=null;const text=await res.text();try{data=text?JSON.parse(text):null}catch{data={error:text}}if(!res.ok)throw new Error(data?.error||`${res.status} ${res.statusText}`);return data}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className=error?'show error':'show';clearTimeout(el.t);el.t=setTimeout(()=>el.className='',3200)}
function serverPath(path){return `booi/${encodeURIComponent(state.server)}/${path}`}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
async function catalogRows(kind){const key=`${state.server}:${kind}`;if(!catalogRowCache[key])catalogRowCache[key]=api(serverPath(`catalog/${kind}?limit=20000&compact=true`)).then(d=>d.rows);try{return await catalogRowCache[key]}catch(e){delete catalogRowCache[key];throw e}}
async function catalogNames(kind){const key=`${state.server}:${kind}`;if(!catalogNameCache[key])catalogNameCache[key]=catalogRows(kind).then(rows=>Object.fromEntries(rows.filter(x=>x.localized_name).map(x=>[String(x.id),x.localized_name])));try{return await catalogNameCache[key]}catch(e){delete catalogNameCache[key];throw e}}
async function loadAssetTypeOptions(){if(!assetTypeOptionCache)assetTypeOptionCache=catalogRows('item-types').then(rows=>rows.map(row=>{const exact=row.fallback_name||'',localized=row.localized_name||'',name=exact&&localized&&exact!==localized?`${exact}（${localized}）`:exact||localized||'未命名类型';return {value:Number(row.id),name,label:`${row.id} · ${name}`}}).sort((a,b)=>a.value-b.value));return assetTypeOptionCache}
async function assetTypeOptions(selected){try{const options=await loadAssetTypeOptions();if(selected!==undefined&&selected!==null&&!options.some(x=>String(x.value)===String(selected)))return [{value:Number(selected),name:'未知类型',label:`${selected} · 未知类型`},...options];return options}catch(e){assetTypeOptionCache=null;toast('资产类型目录加载失败：'+e.message,true);return [{value:Number(selected)||1,name:'未知类型',label:`${Number(selected)||1} · 未知类型`}]}}
const resourceTypeLabels={items:'资产',cards:'思念',fashions:'皮肤',stages:'关卡',tasks:'任务',unlocks:'系统解锁',guides:'引导组',roles:'男主角色'};
async function resourceOptions(kind,selected){const key=`${state.server}:${kind}`;try{if(!resourceOptionCache[key])resourceOptionCache[key]=Promise.all([catalogRows(kind),kind==='items'?loadAssetTypeOptions():Promise.resolve([])]).then(([rows,types])=>{const typeNames=Object.fromEntries(types.map(x=>[String(x.value),x.name]));return rows.map(row=>{const name=row.localized_name||row.fallback_name||'未找到名称',type=kind==='items'?`资产 / ${typeNames[String(row.asset_type)]||`类型 ${row.asset_type||'未知'}`}`:resourceTypeLabels[kind]||kind,label=`${row.id} · ${name} · ${type}`;return {value:String(row.id),label,searchLower:`${row.id} ${name} ${type}`.toLowerCase(),assetType:Number(row.asset_type)||0}})});const options=await resourceOptionCache[key];if(selected!==undefined&&selected!==null&&selected!==''&&!options.some(x=>String(x.value)===String(selected))){const label=`${selected} · 未找到名称 · ${resourceTypeLabels[kind]||kind}`;return [{value:String(selected),label,searchLower:label.toLowerCase()},...options]}return options}catch(e){delete resourceOptionCache[key];toast(`${resourceTypeLabels[kind]||kind}目录加载失败：${e.message}`,true);return selected!==undefined&&selected!==null&&selected!==''?[{value:String(selected),label:`${selected} · 未找到名称`,searchLower:String(selected).toLowerCase()}]:[]}}
async function accountOptions(){const d=await api('sdk/accounts?q=');return d.accounts.filter(a=>!a.deleted_at).map(a=>({value:String(a.id),label:`${a.id} · ${a.phone} · SDK 账号`,search:`${a.id} ${a.phone} SDK 账号`}))}
function localizedName(kind,id){return state.names?.[kind]?.[String(id)]||''}
function nameCell(kind,id){return esc(localizedName(kind,id)||'—')}
function namedID(kind,id,empty='-'){if(!id)return empty;const name=localizedName(kind,id);return name?`${id} · ${esc(name)}`:String(id)}
function localTime(value){return value?new Date(value*1000).toLocaleString('zh-CN'):'-'}
let modalSearchSerial=0;
function createSearchSelect(field,form){const wrap=document.createElement('div'),input=document.createElement('input'),menu=document.createElement('div'),options=field.options||[];wrap.className='modal-search-select';menu.className='modal-search-menu';menu.id=`modal-search-menu-${++modalSearchSerial}`;menu.hidden=true;menu.setAttribute('role','listbox');input.type='search';input.name=field.name;input.autocomplete='off';input.placeholder=field.placeholder||'输入编号、名称或类型搜索';input.setAttribute('role','combobox');input.setAttribute('aria-autocomplete','list');input.setAttribute('aria-haspopup','listbox');input.setAttribute('aria-controls',menu.id);input.setAttribute('aria-expanded','false');input.readOnly=!!field.readonly;let active=-1,visible=[],renderTimer=0;const hide=()=>{menu.hidden=true;input.setAttribute('aria-expanded','false');active=-1};const choose=(option,notify=true)=>{input.value=option.label;input.dataset.value=String(option.value);input.setCustomValidity('');hide();if(notify&&field.onSelect)field.onSelect(option,form)};input.setChoice=value=>{const option=options.find(x=>String(x.value)===String(value));if(option)choose(option,false)};const mark=next=>{const buttons=[...menu.querySelectorAll('button')];if(!buttons.length)return;active=(next+buttons.length)%buttons.length;buttons.forEach((button,i)=>button.classList.toggle('active',i===active));buttons[active].scrollIntoView({block:'nearest'})};const render=()=>{const query=(input.dataset.value?'':input.value).trim().toLowerCase(),terms=query.split(/\s+/).filter(Boolean);visible=[];for(const option of options){const haystack=option.searchLower||(option.search||option.label).toLowerCase();if(terms.every(term=>haystack.includes(term))){visible.push(option);if(visible.length===80)break}}menu.replaceChildren();if(!visible.length){const empty=document.createElement('div');empty.className='modal-search-empty';empty.textContent='没有匹配项';menu.append(empty)}else for(const option of visible){const button=document.createElement('button');button.type='button';button.setAttribute('role','option');button.textContent=option.label;button.onmousedown=e=>e.preventDefault();button.onclick=()=>choose(option);menu.append(button)}menu.hidden=false;input.setAttribute('aria-expanded','true');active=-1;requestAnimationFrame(()=>{const rect=input.getBoundingClientRect(),spaceBelow=innerHeight-rect.bottom;menu.classList.toggle('up',spaceBelow<Math.min(250,menu.scrollHeight)+12&&rect.top>spaceBelow)})};const scheduleRender=()=>{clearTimeout(renderTimer);renderTimer=setTimeout(()=>{renderTimer=0;render()},70)};const selected=options.find(x=>String(x.value)===String(field.value));if(selected)choose(selected,false);else if(field.value!==undefined&&field.value!==null&&field.value!==''){input.value=String(field.value);input.dataset.value=String(field.value)}if(!field.readonly){input.onfocus=render;input.oninput=()=>{input.dataset.value='';input.setCustomValidity('');scheduleRender()};input.onblur=()=>setTimeout(hide,120);input.onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();if(menu.hidden)render();mark(active+1)}else if(e.key==='ArrowUp'){e.preventDefault();if(menu.hidden)render();mark(active<0?visible.length-1:active-1)}else if(e.key==='Enter'){if(renderTimer){clearTimeout(renderTimer);renderTimer=0;render()}if(!menu.hidden&&visible.length){e.preventDefault();choose(visible[active<0?0:active])}}else if(e.key==='Escape')hide()}}wrap.append(input,menu);return input}
function showModal({title,message='',fields=[],submitText='确定',danger=false}){const dialog=$('#app-modal'),form=$('#modal-form'),container=$('#modal-fields'),messageEl=$('#modal-message'),submit=$('#modal-submit');dialog.classList.toggle('editor-modal',fields.length>0);$('#modal-title').textContent=title;messageEl.textContent=message;messageEl.hidden=!message;container.replaceChildren();submit.textContent=submitText;submit.className=danger?'danger':'primary';for(const field of fields){const label=document.createElement('label');label.className=field.type==='checkbox'?'modal-check':'modal-field';let input;if(field.type==='search-select')input=createSearchSelect(field,form);else{input=document.createElement(field.type==='textarea'?'textarea':field.type==='select'?'select':'input');input.name=field.name;if(field.type==='checkbox'){input.type='checkbox';input.checked=!!field.value;label.append(input,document.createTextNode(field.label))}else if(field.type==='select'){for(const option of field.options||[]){const node=document.createElement('option');node.value=option.value;node.textContent=option.label;node.selected=String(option.value)===String(field.value);input.append(node)}}else{input.type=field.type||'text';input.value=field.value??''}}if(field.type!=='checkbox'){const caption=document.createElement('span');caption.textContent=field.label;if(field.placeholder&&field.type!=='search-select')input.placeholder=field.placeholder;if(field.required&&field.type!=='search-select')input.required=true;if(field.readonly)input.readOnly=true;if(field.min!==undefined)input.min=field.min;if(field.max!==undefined)input.max=field.max;if(field.step!==undefined)input.step=field.step;if(field.minlength!==undefined)input.minLength=field.minlength;if(field.maxlength!==undefined)input.maxLength=field.maxlength;if(field.autocomplete&&field.type!=='search-select')input.autocomplete=field.autocomplete;label.append(caption,field.type==='search-select'?input.parentElement:input)}container.append(label)}return new Promise(resolve=>{let settled=false;const finish=value=>{if(settled)return;settled=true;form.onsubmit=null;dialog.oncancel=null;dialog.onclick=null;$('#modal-cancel').onclick=null;$('#modal-close').onclick=null;if(dialog.open)dialog.close();resolve(value)};form.onsubmit=e=>{e.preventDefault();if(!form.reportValidity())return;const values={};for(const field of fields){const input=form.elements.namedItem(field.name);if(field.type==='search-select'){let selected=input.dataset.value;if(!selected){const match=(field.options||[]).find(option=>String(option.value)===input.value||option.label===input.value);if(match){selected=String(match.value);input.dataset.value=selected}else if(field.required){input.setCustomValidity(`请从下拉菜单中选择有效的${field.label}`);input.reportValidity();return}}values[field.name]=selected||''}else values[field.name]=field.type==='checkbox'?input.checked:input.value}finish(values)};dialog.oncancel=e=>{e.preventDefault();finish(null)};dialog.onclick=e=>{if(e.target===dialog)finish(null)};$('#modal-cancel').onclick=()=>finish(null);$('#modal-close').onclick=()=>finish(null);dialog.showModal();const first=container.querySelector('input:not([type=checkbox]):not([readonly]),select,textarea');if(first)setTimeout(()=>first.focus(),0)})}
function confirmModal(title,message,submitText='确定',danger=false){return showModal({title,message,submitText,danger})}
async function boot(){try{const h=await api('health');$('#health').textContent='服务在线';$('#health').classList.add('ok');$('#server').innerHTML=h.booi_servers.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');state.server=$('#server').value;$('#player-back-btn')?.addEventListener('click',()=>{$('.split')?.classList.remove('show-detail')});await loadPlayers();}catch(e){toast(e.message,true);$('#health').textContent='服务异常';$('#health').classList.remove('ok');$('#health').classList.add('danger')}}
