$('#server').onchange=()=>{state.server=$('#server').value;state.player=null;state.data=null;state.names={};state.listViews={};assetTypeOptionCache=null;$('.split')?.classList.remove('show-detail');$('#player-detail').hidden=true;$('#player-empty').hidden=false;loadPlayers()};
