async function loadPlayers(){try{const d=await api(serverPath('players?q='+encodeURIComponent($('#player-query').value)));$('#player-list').innerHTML=d.players.map(p=>{const badges=`<span class="record-tag level">Lv.${p.level||1}</span>${p.deleted_at?'<span class="record-tag danger">已注销</span>':''}${p.deletion_due_at?'<span class="record-tag warning">等待注销</span>':''}${p.banned?'<span class="record-tag warning">已封禁</span>':''}`;return `<div class="record ${state.player==p.account_id?'active':''}" data-player="${p.account_id}"><div class="record-title"><b>${esc((p.family_name||'')+(p.name||'未命名'))}</b><span class="record-badges">${badges}</span></div><span>#${p.account_id} · OpenID ${esc(p.openid||'未绑定')}</span></div>`}).join('')||'<div class="empty">没有玩家</div>';$$('[data-player]').forEach(x=>x.onclick=()=>selectPlayer(x.dataset.player))}catch(e){toast(e.message,true)}}
async function selectPlayer(id){const selected=Number(id);state.player=selected;state.names={};state.listViews={};try{const data=await api(serverPath('players/'+selected));if(state.player!==selected)return;state.data=data;$('#player-empty').hidden=true;$('#player-detail').hidden=false;$('.split')?.classList.add('show-detail');renderPlayer();loadPlayers()}catch(e){toast(e.message,true)}}
const tabNameKinds={overview:['stages'],assets:['items'],cards:['cards'],fashions:['fashions'],progress:['stages','unlocks','roles'],tasks:['tasks']};
function ensureTabNames(){const player=state.player,server=state.server,tab=state.tab;for(const kind of tabNameKinds[tab]||[]){if(state.names[kind])continue;const key=`${server}:${kind}`;if(!nameLoadPending[key])nameLoadPending[key]=catalogNames(kind).finally(()=>delete nameLoadPending[key]);nameLoadPending[key].then(names=>{if(state.player!==player||state.server!==server)return;state.names[kind]=names;if(state.tab===tab)renderTab()}).catch(e=>toast(`${resourceTypeLabels[kind]||kind}名称加载失败：${e.message}`,true))}}
function wireIdentityAction(id,action){const button=$(`#${id}`);button.onclick=e=>{e.preventDefault();e.stopPropagation();button.closest('details')?.removeAttribute('open');void action()}}
