async function refreshPlayer(msg='已保存'){state.data=await api(serverPath('players/'+state.player));renderPlayer();toast(msg)}
async function editProfile(){const p=state.data.profile,v=await showModal({title:'编辑玩家资料',fields:[{name:'family_name',label:'姓氏',value:p.family_name},{name:'name',label:'名字',value:p.name},{name:'level',label:'猎人等级',type:'number',value:p.level,min:1,step:1,required:true}]});if(!v)return;try{const r=await api(serverPath(`players/${state.player}/profile`),{method:'PATCH',body:JSON.stringify({family_name:v.family_name,name:v.name,level:Number(v.level)})});await refreshPlayer(`已保存，实时通知 ${r.notified} 个会话`)}catch(e){toast(e.message,true)}}
async function editCharge(){const old=state.data.charge||{},v=await showModal({title:'修改充值状态',fields:[{name:'first_state',label:'首充状态',type:'select',value:old.first_state??0,options:[{value:0,label:'未达成'},{value:1,label:'可领取'},{value:2,label:'已领取'}]},{name:'total',label:'累计充值金额',type:'number',value:old.total??0,min:0,step:1,required:true},{name:'total_count',label:'累计充值次数',type:'number',value:old.total_count??0,min:0,step:1,required:true}]});if(!v)return;try{const body={...old,first_state:Number(v.first_state),total:Number(v.total),total_count:Number(v.total_count),first_charge:old.first_charge||{charges:{},last_reset_time:0,charges_before_reset:{}}};const r=await api(serverPath(`players/${state.player}/charge`),{method:'PUT',body:JSON.stringify(body)});await refreshPlayer(`充值状态已保存，实时通知 ${r.notified} 个会话`)}catch(e){toast(e.message,true)}}
async function toggleBan(){try{if(state.data.ban){if(!await confirmModal('解除封禁','确定解除该玩家的封禁状态？','解除封禁'))return;await api(serverPath(`players/${state.player}/ban`),{method:'DELETE'})}else{const localDateTime=date=>new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16),minimumEnd=localDateTime(new Date(Date.now()+60000)),defaultEnd=localDateTime(new Date(Date.now()+86400000));const v=await showModal({title:'封禁玩家',message:'永久封禁不显示截止时间；定时封禁使用当前设备的本地时间。多语言原因会按客户端语言显示。',fields:[{name:'ban_type',label:'封禁类型',type:'select',value:'permanent',options:[{value:'permanent',label:'永久封禁'},{value:'timed',label:'定时封禁'}],required:true},{name:'end_time',label:'截止时间（定时封禁时使用）',type:'datetime-local',value:defaultEnd,min:minimumEnd},{name:'reason_zh_cn',label:'原因 · 简体中文',value:'管理员封禁',required:true,maxlength:120},{name:'reason_zh_tw',label:'原因 · 繁體中文',value:'管理員封禁',maxlength:120},{name:'reason_en',label:'Reason · English',value:'Account suspended by administrator',maxlength:120},{name:'reason_jp',label:'理由 · 日本語',value:'管理者によるアカウント停止',maxlength:120},{name:'reason_ko',label:'사유 · 한국어',value:'관리자에 의해 계정이 정지되었습니다',maxlength:120}],submitText:'确认封禁',danger:true});if(!v)return;const fallback=v.reason_zh_cn.trim();let endTime=0;if(v.ban_type==='timed'){const milliseconds=new Date(v.end_time).getTime();if(!v.end_time||!Number.isFinite(milliseconds)||milliseconds<=Date.now())return toast('定时封禁的截止时间必须晚于当前时间',true);endTime=Math.floor(milliseconds/1000)}const message=JSON.stringify([{lang:'zh-cn',text:fallback},{lang:'zh-tw',text:v.reason_zh_tw.trim()||fallback},{lang:'en',text:v.reason_en.trim()||fallback},{lang:'jp',text:v.reason_jp.trim()||fallback},{lang:'ko',text:v.reason_ko.trim()||fallback}]);await api(serverPath(`players/${state.player}/ban`),{method:'PUT',body:JSON.stringify({EndTime:endTime,Reason:1,Message:message})})}await refreshPlayer()}catch(e){toast(e.message,true)}}
async function disconnectPlayer(){if(!await confirmModal('断开玩家连接','向在线客户端发送下线协议，并撤销该角色的全部临时游戏令牌？','断开连接',true))return;try{const r=await api(serverPath(`players/${state.player}/disconnect`),{method:'POST',body:'{}'});toast(`已通知 ${r.notified} 个在线会话，撤销 ${r.revoked_tickets} 个临时令牌`)}catch(e){toast(e.message,true)}}
async function movePlayer(){const source=state.player,v=await showModal({title:'移动角色 UID',message:'所有属于该角色的数据和外键都会递归迁移；目标 UID 必须为空。',fields:[{name:'target_account_id',label:'目标 UID',type:'number',min:1,step:1,required:true}],submitText:'移动角色',danger:true});if(!v)return;const target=Number(v.target_account_id);if(target===source)return toast('目标 UID 不能与当前 UID 相同',true);try{await api(serverPath(`players/${source}/move`),{method:'POST',body:JSON.stringify({target_account_id:target})});state.player=target;await loadPlayers();await selectPlayer(target);toast(`角色已从 UID ${source} 移动到 ${target}`)}catch(e){toast(e.message,true)}}
async function copyPlayer(){const source=state.player,v=await showModal({title:'复制角色',message:'目标 UID 已存在时会被完整覆盖。复制包含全部永久玩家数据，但不会复制登录令牌或 OpenID 绑定。',fields:[{name:'target_account_id',label:'目标 UID',type:'number',min:1,step:1,required:true}],submitText:'复制并覆盖',danger:true});if(!v)return;const target=Number(v.target_account_id);if(target===source)return toast('目标 UID 不能与当前 UID 相同',true);try{await api(serverPath(`players/${source}/copy`),{method:'POST',body:JSON.stringify({target_account_id:target})});state.player=target;await loadPlayers();await selectPlayer(target);toast(`角色已完整复制到 UID ${target}，当前未绑定 OpenID`)}catch(e){toast(e.message,true)}}
async function bindPlayer(){try{const options=await accountOptions();if(!options.length)return toast('没有可绑定的有效 SDK 账号',true);const v=await showModal({title:state.data.profile.openid?'换绑 OpenID':'绑定 OpenID',message:'一个 OpenID 同一时间只能绑定一个角色。',fields:[{name:'openid',label:'SDK OpenID（账号 ID）',type:'search-select',options,required:true}],submitText:'确认绑定'});if(!v)return;await api(serverPath(`players/${state.player}/bind`),{method:'POST',body:JSON.stringify({openid:v.openid,restore:!!state.data.deleted_at})});await refreshPlayer('OpenID 绑定已更新')}catch(e){toast(e.message,true)}}
async function unbindPlayer(){if(!await confirmModal('解绑 OpenID','角色及其全部数据会保留，但解绑后无法登录，直到再次绑定。','确认解绑',true))return;try{const r=await api(serverPath(`players/${state.player}/unbind`),{method:'POST',body:'{}'});await refreshPlayer(`OpenID 已解绑，实时通知 ${r.notified||0} 个会话`)}catch(e){toast(e.message,true)}}
async function markPendingDeletion(){if(!await confirmModal('标记等待注销','角色将在 15 天后软注销并解绑 OpenID；冷静期内再次登录会静默取消注销。','标记等待注销',true))return;try{await api(serverPath(`players/${state.player}/pending-deletion`),{method:'POST',body:'{}'});await refreshPlayer('角色已进入 15 天注销冷静期')}catch(e){toast(e.message,true)}}
